--region init
function ActivityCakeShopBossDamageBonusDialog:AddUIClick()
    SetButtonAction(self.BtnClose, Bind(self, self.OnBtnCloseHandler))
    SetButtonAction(self.Fuzzy, Bind(self, self.OnBtnCloseHandler))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnOneKeyDrawHandler))
end

function ActivityCakeShopBossDamageBonusDialog:InitData()
    if isNull(self._damageRewardList) then
        self._damageRewardList = CfUtils.GetCf(AutoIds.IdSetting6247, "ActivityCakeBossHurtVo", true)
    end
    self.bossData = ActivityCakeUtils.GetActivityCakeMgr():GetActivityBossData()
    self._historyMaxHurt = checkNumber(self.bossData.playerRank.damage)
    self._isCanOneKeyDraw = self:IsCanOneKeyDrawReward()
    self:RefreshUI()
end
--endregion init

--region handler
function ActivityCakeShopBossDamageBonusDialog:OnBtnOneKeyDrawHandler()
    if not self._isCanOneKeyDraw then
        return
    end
    self:DrawReward(0)
end

function ActivityCakeShopBossDamageBonusDialog:OnDrawDamageRewardHandler()
    self:InitData()
end

function ActivityCakeShopBossDamageBonusDialog:OnBtnCloseHandler()
    UIModule.CloseDialog(self.controller)
end
--endregion handler

--region private
function ActivityCakeShopBossDamageBonusDialog:InitItemByIndex(listView, index)
    local luaIndex = index + 1
    local cellData = self._damageRewardList[luaIndex]
    local cell = listView:NewListViewItem("Cell")
    ---@type UIActivityMidFestivalBossDamageRewardCell
    local scr = CfUtils.GetLuaScr(cell, "Game.UI.ActivityCakeShopDialog.Cell.ActivityCakeShopBossDamageBonusCell")
    scr:SetCallBack(function(id) self:OnDrawRewardClick(id)  end)
    scr:Refresh(cellData, self._historyMaxHurt)
    return cell
end

function ActivityCakeShopBossDamageBonusDialog:OnDrawRewardClick(id)
    local idHaveDraw = ActivityCakeUtils.GetActivityCakeMgr():IsHaveDrawBossHurtReward(id)
    if idHaveDraw then
        GameUtils.Toast(localize("奖励已经领取"))
        return
    end

    self:DrawReward(id)
end

function ActivityCakeShopBossDamageBonusDialog:DrawReward(id)
    local activityData = ActivityCakeUtils.GetActivityCakeMgr():GetActivityData()
    GameUtils.Request(Interfaces.OverseaActivityCatParadiseReceiveBossDamageReward, {activityUuid = activityData.id,rewardId = id} , function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local rewards = jsonData.rewards
        ActivityCakeUtils.GetActivityCakeMgr():UpdateReceiveRewardId(id)

        if #rewards > 0 then
            GoodsUtils.DrawRewards(rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        end
        self:OnDrawDamageRewardHandler()
        ActivityCakeUtils.GetActivityCakeMgr():UpdateBossHurtRedPoint(self._isCanOneKeyDraw)
    end)
end

function ActivityCakeShopBossDamageBonusDialog:RefreshUI()
    CfUtils.SetActive(self.FontStyleButton, self._isCanOneKeyDraw)

    if not self.DamageLoopView.IsListViewInit then
        self.DamageLoopView:InitListView(#self._damageRewardList, Bind(self, self.InitItemByIndex))
    else
        GameUtils.ReloadData(self.DamageLoopView, #self._damageRewardList)
    end
end
--endregion private

--region public
function ActivityCakeShopBossDamageBonusDialog:IsCanOneKeyDrawReward()
    -- 获取所有奖励
    local allRewards = self._damageRewardList
    -- 获取所有可领取的奖励
    local historyMaxHurt = self._historyMaxHurt
    local allCanDrawButNotInListRewards = {}
    for _, reward in ipairs(allRewards) do
        ---@type MidFestivalBossDamageRewardVo
        local rewardVo = reward
        if historyMaxHurt >= checkNumber(rewardVo.upperLimit) and (not ActivityCakeUtils.GetActivityCakeMgr():IsHaveDrawBossHurtReward(rewardVo.id)) then
            table.insert(allCanDrawButNotInListRewards, rewardVo)
        end
    end
    return table.count(allCanDrawButNotInListRewards) > 0
end
--endregion public

